// Build one readable alert from the Error Trigger payload.
return $input.all().map(({ json }) => {
  const exec = json.execution ?? {};
  const wf = json.workflow ?? {};
  const failedNode = exec.lastNodeExecuted || exec.error?.node?.name || 'unknown node';
  const message = String(exec.error?.message || json.trigger?.error?.message || 'Unknown error').slice(0, 500);
  const when = new Date().toISOString().replace('T', ' ').slice(0, 16) + ' UTC';
  return { json: {
    workflowName: wf.name || 'Unknown workflow',
    failedNode,
    message,
    executionUrl: exec.url || '',
    mode: exec.mode || '',
    when,
    text: `:rotating_light: *${wf.name || 'A workflow'}* failed at *${failedNode}*\n> ${message}\n${exec.url ? '<' + exec.url + '|Open execution>' : ''}  (${when})`,
  } };
});
